CREATE TABLE operations_schema (id INTEGER PRIMARY KEY CHECK (id = 1), identity TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE principals (principal_id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('local-operator','delegated')), source TEXT NOT NULL CHECK (source IN ('server-local','server-delegated')), parent_principal_id TEXT REFERENCES principals(principal_id), created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_local_operator ON principals(kind) WHERE kind = 'local-operator';
CREATE TABLE sessions (session_id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK (version > 0), status TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(principal_id), requested_profile_id TEXT NOT NULL, resolved_profile_id TEXT NOT NULL, surface_id TEXT NOT NULL, delegated_principal_id TEXT REFERENCES principals(principal_id), parent_session_id TEXT REFERENCES sessions(session_id), owner_principal_id TEXT NOT NULL REFERENCES principals(principal_id), authorization_scope TEXT NOT NULL, snapshot_json BLOB NOT NULL CHECK (length(snapshot_json) <= 262144), exposure_json BLOB NOT NULL CHECK (length(exposure_json) <= 262144), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE session_turns (turn_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, ordinal INTEGER NOT NULL CHECK (ordinal > 0), idempotency_key TEXT NOT NULL, expected_version INTEGER NOT NULL, resulting_version INTEGER NOT NULL, run_id TEXT NOT NULL, status TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(principal_id), surface_id TEXT NOT NULL, delegated_principal_id TEXT REFERENCES principals(principal_id), parent_turn_id TEXT REFERENCES session_turns(turn_id), owner_principal_id TEXT NOT NULL REFERENCES principals(principal_id), authorization_scope TEXT NOT NULL, usage_json BLOB NOT NULL CHECK (length(usage_json) <= 16384), created_at INTEGER NOT NULL, completed_at INTEGER, UNIQUE(session_id, ordinal), UNIQUE(session_id, idempotency_key));
CREATE TABLE session_entries (entry_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES session_turns(turn_id) ON DELETE CASCADE, ordinal INTEGER NOT NULL CHECK (ordinal > 0), entry_kind TEXT NOT NULL, body BLOB NOT NULL CHECK (length(body) <= 262144), metadata BLOB NOT NULL CHECK (length(metadata) <= 16384), principal_id TEXT NOT NULL REFERENCES principals(principal_id), surface_id TEXT NOT NULL, delegated_principal_id TEXT REFERENCES principals(principal_id), parent_entry_id TEXT REFERENCES session_entries(entry_id), owner_principal_id TEXT NOT NULL REFERENCES principals(principal_id), authorization_scope TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(session_id, ordinal));
CREATE TABLE outbox (sequence INTEGER PRIMARY KEY AUTOINCREMENT, stream_scope TEXT NOT NULL CHECK (stream_scope = 'operations'), scope_id TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE, occurred_at INTEGER NOT NULL, schema_version TEXT NOT NULL CHECK (schema_version = 'prowl.operations.event/v1'), resource_kind TEXT NOT NULL, resource_id TEXT NOT NULL, resource_version INTEGER NOT NULL, event_kind TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(principal_id), requested_profile_id TEXT NOT NULL, resolved_profile_id TEXT NOT NULL, surface_id TEXT NOT NULL, delegated_principal_id TEXT REFERENCES principals(principal_id), parent_event_id TEXT, owner_principal_id TEXT NOT NULL REFERENCES principals(principal_id), authorization_scope TEXT NOT NULL, correlation_id TEXT NOT NULL, causation_id TEXT NOT NULL, metadata BLOB NOT NULL CHECK (length(metadata) <= 4096));
CREATE TRIGGER outbox_immutable_update BEFORE UPDATE ON outbox BEGIN SELECT RAISE(ABORT, 'operations outbox rows are immutable'); END;
CREATE TABLE authority (id INTEGER PRIMARY KEY CHECK (id = 1), stream_scope TEXT NOT NULL CHECK (stream_scope = 'operations'), scope_id TEXT NOT NULL, epoch INTEGER NOT NULL CHECK (epoch > 0), retention_floor INTEGER NOT NULL CHECK (retention_floor >= 0), snapshot_uri TEXT NOT NULL, publisher_watermark INTEGER NOT NULL CHECK (publisher_watermark >= 0));
